#![allow(unused)]
use vstd::prelude::*;

verus! {
    /// Pure helper to compute the minimum of two i8's.
    spec fn min_i8(a: i8, b: i8) -> i8 {
        if a <= b { a } else { b }
    }

    /// solve(n, k) returns [x_min, x_max] satisfying:
    ///  • If k==0 or k==n then both are 0.
    ///  • Else x_min=1 and x_max = min(n-k, 2*k).
    ///  • Always 0 ≤ x_min ≤ x_max ≤ n−k.
    fn solve(n: i8, k: i8) -> Vec<i8>
        requires 1 <= n
        requires 0 <= k && k <= n
        ensures  result.len() == 2
        ensures  0 <= result[0]
        ensures  0 <= result[1]
        ensures  result[0] <= result[1]
        ensures  result[0] <= n - k
        ensures  result[1] <= n - k
        ensures
            if k == 0 || k == n {
                result[0] == 0 && result[1] == 0
            } else {
                result[0] == 1 && result[1] == min_i8(n - k, k * 2)
            }
    {
        let mut res: Vec<i8> = Vec::new();
        if k == 0 || k == n {
            // No selected or all selected: no "good" unselected items possible.
            res.push(0);
            res.push(0);
        } else {
            // Some but not all selected:
            //   x_min = 1
            //   x_max = min(n - k, 2*k)
            let x_min: i8 = 1;
            let rem: i8 = n - k;
            let dbl: i8 = k * 2;
            let x_max: i8 = if rem <= dbl { rem } else { dbl };
            res.push(x_min);
            res.push(x_max);
        }
        // At this point, res.len() == 2 and all the ensures can be discharged.
        res
    }
}